// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 depositAmount, address caller) public {
        depositAmount = bound(depositAmount, 1, 1 ether);
        vm.assume(caller != address(this));

        vm.deal(caller, depositAmount);

        vm.prank(caller);
        (bool sent,) = address(c).call{value: depositAmount}("");
        require(sent);

        assert(address(c).balance == depositAmount);

        bool ok;
        vm.prank(caller);
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        address owner = c.owner();
        if (caller != owner) {
            assertTrue(!ok || address(c).balance == depositAmount);
        } else {
            assertTrue(true);
        }
    }
}
